"""Acceptance coverage for public collection paging validation."""

import pytest

from gitseed.collect.search import collect


class RecordingTransport:
    def __init__(self) -> None:
        self.urls: list[str] = []

    def get(self, url: str) -> tuple[int, dict[str, str], bytes]:
        self.urls.append(url)
        return 200, {}, b'{"items": []}'


@pytest.mark.parametrize(
    ("argument", "value"),
    [
        ("pages", 0),
        ("pages", -1),
        ("per_page", 0),
        ("per_page", -1),
        ("per_page", 101),
    ],
)
def test_collect_rejects_invalid_paging_before_request(
    argument: str, value: int
) -> None:
    transport = RecordingTransport()

    with pytest.raises(ValueError):
        collect("topic", transport=transport, **{argument: value})

    assert transport.urls == []


@pytest.mark.parametrize("per_page", [1, 100])
def test_collect_accepts_github_per_page_boundaries(per_page: int) -> None:
    transport = RecordingTransport()

    collect("topic", transport=transport, pages=1, per_page=per_page)

    assert len(transport.urls) == 1
